INSERT INTO wiki_pages (path,title,summary,commit_sha,content_sha,updated_at,metadata_json) VALUES ('wiki/sources/uber-taf-tap-tsi.md','Über TAF/TAP TSI','Bis zur Einführung von TAF/TAP TSI werden wir unsere Kund:innen so intensiv und detailliert wie möglich informieren und durch diese Veränderung begleiten. Auf dieser Informationsplattform werden alle relevanten Informationen und Unterlagen übersichtlich gebündelt und selbstverständlich regelmäßig aktualisiert und ergänzt. Stärkere Wettbewerbsfähigkeit Weiter','bootstrap:fc1ae193dc71eb162b39f9417842eeabf3fe897760e0b1ed64c8da7378775900','6304a9ca9cd6ca7793909267b868b432adfc416f32434a020e80b8636b79d37e','2026-08-02T10:25:48Z','{"bootstrap":true,"canonical_url":"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/allgemein-11089206","license":"unknown","origin_page_url":"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-tap-tsi/allgemein-11089206","source_id":"src_0ed972984c152ac37d60","source_version_id":"sv_7c633488c07b24cabd17e8b9"}') ON CONFLICT(path) DO UPDATE SET title=excluded.title,summary=excluded.summary,commit_sha=excluded.commit_sha,content_sha=excluded.content_sha,updated_at=excluded.updated_at,metadata_json=excluded.metadata_json;
